import {states,createSession,score,recordAnswer,blankStats,validSession} from './engine.js';
import {translate,localizedQuestion} from './i18n.js';
const app=document.querySelector('#app'), LANGUAGE_KEY='nj-road-ready-language', STATE_KEY='road-ready-state';
let state='nj',config=states.nj,questions=config.questions,topics=config.topics;
function loadState(next){
 state=next;config=states[state];questions=config.questions;topics=config.topics;stats=blankStats();session=null;manual=null;
 try{const old=JSON.parse(localStorage.getItem(config.storageKey)||'null');if(old?.stats&&Array.isArray(old.stats.missed)&&Array.isArray(old.stats.seen)&&Array.isArray(old.stats.history)&&old.stats.topics){stats={...blankStats(),...old.stats};stats.missed=stats.missed.filter(id=>questions.some(q=>q.id===id));if(validSession(old.session)&&(old.session.state??'nj')===state)session=old.session;}}catch{storageOK=false;}
}
function setState(next){if(!Object.hasOwn(states,next)||next===state)return;save();loadState(next);try{localStorage.setItem(STATE_KEY,state);}catch{storageOK=false;}go('home');}
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let stats=blankStats(),session=null,view='home',storageOK=true,offlineReady=false,deferredInstall=null,manual=null,language='en',timerMinutes=0;
try{
 language=localStorage.getItem(LANGUAGE_KEY)==='ka'?'ka':'en';
 loadState(localStorage.getItem(STATE_KEY)==='ny'?'ny':'nj');
}catch{storageOK=false;}
const t=(key,values)=>translate(language,key,values);
const question=id=>localizedQuestion(questions.find(q=>q.id===id),language);
const button=(label,attrs='',kind='secondary')=>`<button class="${kind}" ${attrs}>${t(label)}</button>`;
const sourceButton=page=>`<button class="quiet source" data-page="${page}">${t('Read manual page {n}',{n:page})}</button>`;
function save(){try{localStorage.setItem(config.storageKey,JSON.stringify({stats,session}));}catch{storageOK=false;}}
function go(next){view=next;render();window.scrollTo({top:0,behavior:'instant'});app.querySelector('h1')?.focus({preventScroll:true});}
function setLanguage(next){
 if(!['en','ka'].includes(next))return;
 timerMinutes=Number(document.querySelector('#duration')?.value||timerMinutes);
 language=next;try{localStorage.setItem(LANGUAGE_KEY,language);}catch{storageOK=false;}
 render();
}
function statePicker(){return `<div class="state-picker" role="group" aria-label="${t('Choose your state')}">${Object.entries(states).map(([id,c])=>`<button data-state="${id}" aria-pressed="${state===id}" class="${state===id?'primary':'secondary'}">${id.toUpperCase()} · ${t(c.name)}</button>`).join('')}</div>`;}
function nav(){return `<nav class="nav" aria-label="${t('Main')}">${[['home','Practice'],['progress','My progress'],['guide','Study guide']].map(([id,label])=>`<button data-view="${id}" class="${view===id?'active':''}">${t(label)}</button>`).join('')}</nav>`;}
function home(){return `${nav()}
 <section class="intro"><p class="eyebrow">${t('YOUR NEXT STOP: CONFIDENCE')}</p><h1 tabindex="-1">${t('A little practice.')}<br>${t('A safer driver.')}</h1><p>${t('Learn the rules. Understand the why. Take it one question at a time.')}</p></section>
 ${session&&!session.finished?`<div class="notice row">${t(session.mode==='exam'?'You have an unfinished mock test.':'You have an unfinished practice session.')}<button class="secondary" data-action="resume">${t('Continue question {n}',{n:session.index+1})}</button></div><br>`:''}
 <section class="launch"><div><span class="pill">${t('10 QUESTIONS · INSTANT FEEDBACK')}</span><h2>${t('Your daily drive')}</h2><p>${t('A fresh mix of road rules, signs, and everyday driving decisions.')}</p>${button('Start quick practice →','data-start="quick"','primary')}</div><div class="exam-mini"><p class="eyebrow">${t('THE KNOWLEDGE TEST')}</p><strong>${config.pass}<span> / ${config.count}</span></strong><p>${t('Correct answers needed to pass.')}${config.signs?`<br>${t('Also: at least 2 of 4 road signs correct.')}`:''}</p></div></section>
 <section class="cards" aria-label="${t('Practice modes')}">
 <article class="card"><p class="eyebrow">${t('TEST YOURSELF')}</p><h3>${t('Full mock test')}</h3><p>${t('{total} questions. Answers revealed at the end. Pass with {percent}%.',{total:config.count,percent:config.pass/config.count*100})}${config.signs?` ${t('Also: at least 2 of 4 road signs correct.')}`:''}</p><label class="source" for="duration">${t('Practice timer')}</label><select id="duration" style="width:100%;margin:8px 0">${[[0,'No time limit'],[30,'30-minute challenge'],[50,'50-minute challenge']].map(([n,s])=>`<option value="${n}" ${timerMinutes===n?'selected':''}>${t(s)}</option>`).join('')}</select>${button('Take a mock test','data-start="exam"')}</article>
 <article class="card"><p class="eyebrow">${t('SPOT THE SIGNAL')}</p><h3>${t('Signs & signals')}</h3><p>${t('Recognize real signs from your manual and learn what to do next.')}</p>${button('Practice road signs','data-start="topic" data-topic="Signs & signals"')}</article>
 <article class="card"><p class="eyebrow">${t('MAKE IT STICK')}</p><h3>${t('Learn from mistakes')}</h3><p>${stats.missed.length?t('{n} questions to revisit. Correct answers clear them from your list.',{n:stats.missed.length}):t('Missed questions collect here automatically. A fresh chance to get them right.')}</p><button class="secondary" data-start="mistakes" ${stats.missed.length?'':'disabled'}>${t('Review mistakes')}${stats.missed.length?` (${stats.missed.length})`:''}</button></article></section>
 <div class="section-head"><h2>${t('Practice by topic')}</h2><span class="source">${t('{n} original questions',{n:questions.length})}</span></div><section class="topic-grid">${topics.map(topic=>`<button class="topic" data-start="topic" data-topic="${esc(topic)}"><div>${t(topic)}<span>${t('{n} questions',{n:questions.filter(q=>q.topic===topic).length})}${stats.topics[topic]?.answers?` · ${t('{n}% accuracy',{n:Math.round(stats.topics[topic].correct/stats.topics[topic].answers*100)})}`:''}</span></div><span aria-hidden="true">→</span></button>`).join('')}</section>
 ${language==='ka'?`<p class="notice">${t('Georgian is a study translation, not an official DMV or MVC translation. Original road-sign lettering and US measurement units are preserved.')}</p>`:''}
 ${installHelp()}<p class="source">${t('Mock test format:')} <a href="${config.testUrl}" target="_blank" rel="noopener">${t('{state}: {total} questions, {pass} correct to pass',{state:t(config.name),total:config.count,pass:config.pass})}</a>. ${t('Timed challenges are optional practice settings, not a claim about the official test’s time limit.')}</p>`;}
function installHelp(){return `<details class="notice install"><summary>${t('Keep Road Ready on your phone')}</summary><p><strong>iPhone:</strong> ${t('Open this site in Safari, tap Share, then Add to Home Screen.')} <strong>Android:</strong> ${t('Open in Chrome, then use its menu → Install app or Add to Home screen.')}</p>${deferredInstall?button('Install Road Ready','data-action="install"'):''}<p id="offline-status">${t(offlineReady?'Offline practice is ready on this device.':navigator.onLine?'Preparing offline practice. Keep this page open briefly on your first visit.':'You are offline. Previously saved app content remains available.')}</p><p>${t('Progress is kept separately on each device and browser. Clearing browser data removes it. Hosted sign-in may need a connection.')}</p></details>`;}
function progressView(){return `${nav()}<p class="eyebrow">${t('YOUR LEARNING JOURNEY')}</p><h1 tabindex="-1">${t('See how far you’ve come.')}</h1><div class="stats">${[[stats.answers?Math.round(stats.correct/stats.answers*100)+'%':'—','Answer accuracy'],[`${stats.seen.length}/${questions.length}`,'Questions explored'],[stats.history.length,'Sessions completed']].map(([n,label])=>`<div class="stat"><strong>${n}</strong><span>${t(label)}</span></div>`).join('')}</div>
 <div class="section-head"><h2>${t('Topic confidence')}</h2></div><div class="topic-grid">${topics.map(topic=>{const s=stats.topics[topic];return `<div class="card"><h3>${t(topic)}</h3><p>${s?t('{correct} of {total} attempts correct',{correct:s.correct,total:s.answers}):t('Not practiced yet')}</p><progress class="progress" max="100" value="${s?Math.round(s.correct/s.answers*100):0}" aria-label="${esc(t('{topic} accuracy',{topic:t(topic)}))}"></progress>${button('Practice topic',`data-start="topic" data-topic="${esc(topic)}"`)}</div>`;}).join('')}</div>
 <div class="section-head"><h2>${t('Recent sessions')}</h2></div>${stats.history.length?stats.history.slice().reverse().slice(0,10).map(h=>`<div class="review-item row"><strong>${h.correct}/${h.total}</strong><span>${esc(t(h.label))} · ${new Date(h.date).toLocaleDateString(language==='ka'?'ka-GE':'en-US')}${h.timedOut?` · ${t('Time ended')}`:''}</span></div>`).join(''):`<p class="empty">${t('Finish a practice session to see your results here.')}</p>`}<p class="source">${t('Practice accuracy reflects your attempts, not a prediction of your official test score.')}</p>`;}
function guide(){const chapters=config.chapters;return `${nav()}<p class="eyebrow">${t('YOUR STATE MANUAL')}</p><h1 tabindex="-1">${t('Understand the rule.')}</h1><p>${t('Every question includes a printed-page reference. Read the source here, including offline after the app is saved.')}</p><div class="topic-grid">${chapters.map(([title,page])=>`<button class="topic" data-page="${page}"><div>${t(title)}<span>${t('Manual page {n}',{n:page})}</span></div><span aria-hidden="true">→</span></button>`).join('')}</div><p class="notice">${t('These are original study questions for the basic automobile knowledge test. They do not reproduce the official exam and are not a complete substitute for reading the manual. This app uses the manual you supplied; it does not automatically update when laws change.')}</p><p><a href="${config.pdf}" target="_blank" rel="noopener">${t('Open the official manual PDF online')}</a></p>${installHelp()}`;}
function feedback(q,it){const good=it.selected===q.answer;return `<div class="feedback ${good?'':'wrong'}" role="status"><strong>${t(good?'Correct — nicely done.':'Not quite. Here’s the rule.')}</strong><p>${esc(q.explanation)}</p>${sourceButton(q.page)}</div>`;}
function quiz(){if(!session)return home();if(session.finished)return results();const it=session.items[session.index],q=question(it.id),exam=session.mode==='exam';return `<section class="quiz"><div class="quiz-top">${button('Save & exit','data-view="home"','quiet')}<p>${t(exam?'Mock test':session.topic||'Practice')} · <span class="timer" id="timer">${timeText()}</span></p></div><progress class="progress" value="${session.index}" max="${session.items.length}" aria-label="${t('Question progress')}"></progress><div class="question"><p class="eyebrow">${t('QUESTION {n} OF {total}',{n:session.index+1,total:session.items.length})} · ${t(q.topic)}</p><h1 tabindex="-1">${esc(q.question)}</h1>${q.image?`<img class="sign" src="${q.image}" alt="${t('Road sign to identify; see the visual symbol')}" width="190" height="180">`:''}
 <div class="answers" role="group" aria-label="${t('Answer choices')}">${it.order.map((n,i)=>`<button class="answer ${it.selected===n?'selected':''} ${it.confirmed&&!exam?(n===q.answer?'correct':it.selected===n?'incorrect':''):''}" data-answer="${n}" aria-pressed="${it.selected===n}" ${it.confirmed?'disabled':''}><span class="letter">${(language==='ka'?'აბგდ':'ABCD')[i]}</span><span>${esc(q.options[n])}</span>${it.confirmed&&!exam&&n===q.answer?`<span aria-label="${t('Correct answer')}">✓</span>`:''}</button>`).join('')}</div>
 ${it.confirmed&&!exam?feedback(q,it):''}<div class="question-actions">${!it.confirmed?button(exam?'Save answer':'Check answer',`data-action="confirm" ${it.selected===null?'disabled':''}`,'primary'):button(session.index===session.items.length-1?'See results':'Next question →','data-action="next"','primary')}</div></div><p class="source">${t(exam?'Answers and explanations appear when the test ends.':'Select an answer, then check it to learn why.')} ${t('Your session saves automatically.')}</p></section>`;}
function results(){const s=score(session);return `<section class="quiz">${button('← Back to practice','data-view="home"','quiet')}<div class="intro"><p class="eyebrow">${t(session.timedOut?'TIME’S UP':'SESSION COMPLETE')}</p><h1 tabindex="-1">${t(s.passed?'A strong step forward.':'Keep building your confidence.')}</h1><div class="result-score">${s.correct}<span style="font-size:28px;color:var(--muted)"> / ${s.total}</span></div><p>${t('{n}% correct',{n:s.percent})}${session.mode==='exam'?` · ${s.passed?t('Practice passing target reached'):t('Practice passing target: {pass} of {total}',{pass:config.pass,total:config.count})}${config.signs?` · ${t('Road signs: {correct} of {total} correct (at least 2 required)',{correct:s.signsCorrect,total:s.signsTotal})}`:''}`:''}. ${session.timedOut?t('Unanswered questions count as incorrect.'):''}</p><div class="row">${button('Try another 10','data-start="quick"','primary')}<button class="secondary" data-start="mistakes" ${stats.missed.length?'':'disabled'}>${t('Review mistakes')} (${stats.missed.length})</button></div></div><h2>${t('Review your answers')}</h2>${session.items.map(it=>{const q=question(it.id),ok=it.confirmed&&it.selected===q.answer;return `<article class="review-item"><p class="eyebrow">${t(ok?'✓ CORRECT':'REVISIT')} · ${t(q.topic)}</p>${q.image?`<img src="${q.image}" class="sign" alt="${t('Road sign from this question')}" width="190" height="180">`:''}<h3>${esc(q.question)}</h3><p>${t('Your answer:')} ${it.confirmed?esc(q.options[it.selected]):t('Not answered')}<br><strong>${t('Correct answer:')} ${esc(q.options[q.answer])}</strong></p><p>${esc(q.explanation)}</p>${sourceButton(q.page)}</article>`;}).join('')}</section>`;}
function render(){
 document.documentElement.lang=language;document.title=t('Road Ready — {state} driver practice',{state:t(config.name)});
 const badge=document.querySelector('.badge');if(badge)badge.textContent=state.toUpperCase();
 const languageButton=document.querySelector('#language-toggle');if(languageButton){languageButton.textContent=language==='ka'?'English':'ქართული';languageButton.lang=language==='ka'?'en':'ka';languageButton.setAttribute('aria-label',language==='ka'?'Switch to English':'ქართულ ენაზე გადართვა');}
 const brandSubtitle=document.querySelector('.brand small');if(brandSubtitle)brandSubtitle.textContent=t('DRIVER PRACTICE');
 const edition=document.querySelector('.edition');if(edition)edition.textContent=t(config.name);
 const brand=document.querySelector('.brand');brand?.setAttribute?.('aria-label',t('Road Ready home'));
 const footer=document.querySelector('footer');if(footer)footer.innerHTML=`<section class="l3v-info" aria-label="l3v"><div><p class="l3v-credit">${t('Developed by l3v')}</p><p>${t('Explore l3v tools for names, signatures, and video ideas.')}</p></div><div class="l3v-links"><a class="l3v-link" href="https://l3v.ai/" target="_blank" rel="noopener noreferrer">l3v.ai <span aria-hidden="true">↗</span></a><a class="l3v-link" href="https://tools.l3v.ai/" target="_blank" rel="noopener noreferrer">tools.l3v.ai <span aria-hidden="true">↗</span></a></div></section><p>${t('Independent practice app · Based on the supplied {state} Driver Manual.',{state:t(config.name)})}<br>${t('Not an official exam. Each state’s progress is saved separately on this device.')}</p>`;
 app.innerHTML=statePicker()+(view==='quiz'?quiz():view==='progress'?progressView():view==='guide'?guide():home())+(!storageOK?`<p class="notice" role="status">${t('Your browser is not allowing saved progress. You can still practice, but progress may disappear when you close this page.')}</p>`:'');
}
function start(mode,topic='',minutes=0){if(session&&!session.finished&&!window.confirm(t('Start a new session? This replaces your unfinished session; previously checked answers stay in your progress.')))return false;try{session=createSession(mode,topic,stats.missed,minutes,state);save();go('quiz');return true;}catch(e){window.alert(t(e.message));return false;}}
function confirm(){const it=session?.items[session.index];if(!it||it.confirmed||it.selected===null)return;it.confirmed=true;if(session.mode!=='exam')recordAnswer(stats,questions.find(q=>q.id===it.id),it.selected);save();render();app.querySelector('[data-action="next"]')?.focus({preventScroll:true});}
function finish(timedOut=false){if(session.finished)return;session.finished=true;session.timedOut=timedOut;if(session.mode==='exam')for(const it of session.items){const q=questions.find(q=>q.id===it.id);if(it.confirmed)recordAnswer(stats,q,it.selected);else stats.missed=[...new Set([...stats.missed,q.id])];}const s=score(session);stats.history.push({...s,date:Date.now(),label:session.mode==='exam'?'Mock test':session.topic||'Mixed practice',timedOut});stats.history=stats.history.slice(-100);save();go('quiz');}
function timeText(){if(!session)return '';const sec=Math.max(0,Math.floor(((session.deadline??Date.now())-(session.deadline?Date.now():session.started))/1000));return `${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}${t(session.deadline?' left':' elapsed')}`;}
setInterval(()=>{if(session&&!session.finished){if(session.deadline&&Date.now()>=session.deadline){finish(true);return;}const el=document.querySelector('#timer');if(el)el.textContent=timeText();}},1000);
let sourceDialog=null;
async function showPage(page){
 if(!Number.isInteger(page)||page<1||page>config.pages)return;
 sourceDialog?.remove();const dialog=document.createElement('dialog');sourceDialog=dialog;dialog.className='manual-dialog';document.body.append(dialog);
 dialog.innerHTML=`<p>${t('Loading manual…')}</p>${button('Close','data-close')}`;dialog.showModal();
 dialog.addEventListener('click',e=>{if(e.target.closest('[data-close]'))dialog.close();const target=e.target.closest('[data-manual-page]');if(target)showPage(Number(target.dataset.manualPage));});
 const sourceConfig=config;
 try{manual??=await fetch('./'+sourceConfig.manual).then(r=>{if(!r.ok)throw Error('Manual unavailable');return r.json()});
  dialog.innerHTML=`<div class="row"><h2>${t('Manual page {n}',{n:page})}</h2>${button('Close','data-close')}</div><p class="source">${t('{state} Driver Manual · Original English text. Diagrams and layout are in the original PDF.',{state:t(sourceConfig.name)})}</p><pre lang="en">${esc(manual[page]||'This page has no extractable text. Consult the original PDF for its diagrams.')}</pre><div class="row">${button('Previous page',`data-manual-page="${page-1}" ${page===1?'disabled':''}`,'quiet')}${button('Next page',`data-manual-page="${page+1}" ${page===sourceConfig.pages?'disabled':''}`,'quiet')}<a href="${sourceConfig.pdf}#page=${page+sourceConfig.offset}" target="_blank" rel="noopener">${t('Official PDF online')}</a></div>`;
 }catch{dialog.innerHTML=`<p>${t('The manual text could not load. Reconnect and reopen this page to save it for offline use.')}</p>${button('Close','data-close')}`;}
}
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.state)setState(b.dataset.state);
 else if(b.dataset.action==='language')setLanguage(language==='ka'?'en':'ka');
 else if(b.dataset.view)go(b.dataset.view);
 else if(b.dataset.start)start(b.dataset.start,b.dataset.topic||'',Number(document.querySelector('#duration')?.value||0));
 else if(b.dataset.answer!==undefined&&session&&!session.finished){const it=session.items[session.index];if(!it.confirmed){it.selected=Number(b.dataset.answer);save();render();app.querySelector('[data-action="confirm"]')?.focus({preventScroll:true});}}
 else if(b.dataset.page)showPage(Number(b.dataset.page));
 else if(b.dataset.action==='resume')go('quiz');
 else if(b.dataset.action==='confirm')confirm();
 else if(b.dataset.action==='next'&&session?.items[session.index].confirmed){if(session.index<session.items.length-1){session.index++;save();go('quiz');}else finish();}
 else if(b.dataset.action==='install'&&deferredInstall){await deferredInstall.prompt();deferredInstall=null;render();}
});
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();go('home')});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;if(view!=='quiz')render();});
if('serviceWorker' in navigator){
 let refreshing=false;const hadController=!!navigator.serviceWorker.controller;
 navigator.serviceWorker.addEventListener('controllerchange',()=>{if(hadController&&!refreshing){refreshing=true;window.location.reload();}});
 navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(reg=>{const channel=new MessageChannel();channel.port1.onmessage=e=>{offlineReady=e.data?.ready===true;const el=document.querySelector('#offline-status');if(el)el.textContent=t(offlineReady?'Offline practice is ready on this device.':'Offline saving is still in progress.');};reg.active?.postMessage('status',[channel.port2]);}).catch(()=>{const el=document.querySelector('#offline-status');if(el)el.textContent=t('Offline installation is unavailable in this browser. You can still practice online.');});
}
const mc=document.modelContext;if(mc?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [{name:'get_practice_progress',description:'Read device-local driver practice progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({answers:stats.answers,correct:stats.correct,missed:stats.missed.length,completed:stats.history.length,language,state})},{name:'start_quick_practice',description:'Start a ten-question practice session if no unfinished session exists.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||Object.keys(input).length)throw Error('Expected an empty object');if(session&&!session.finished)throw Error('An unfinished session already exists');start('quick');return {started:true,questions:session.items.length};}}]){try{Promise.resolve(mc.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
render();
